CREATE OR REPLACE FUNCTION ${database.defaultSchemaName}.meta_nombre(m jsonb, code text) RETURNS numeric
LANGUAGE plpgsql IMMUTABLE PARALLEL SAFE AS $corps$
DECLARE
    v text := m ->> code;
BEGIN
    IF v IS NULL OR v !~ '^-?[0-9]+(\.[0-9]+)?([eE][-+]?[0-9]+)?$' THEN
        RETURN NULL;
    END IF;
    RETURN v::numeric;
END
$corps$

CREATE OR REPLACE FUNCTION ${database.defaultSchemaName}.meta_date(m jsonb, code text) RETURNS date
LANGUAGE plpgsql IMMUTABLE PARALLEL SAFE AS $corps$
DECLARE
    v text := m ->> code;
BEGIN
    IF v IS NULL OR v !~ '^[0-9]{4}-[0-9]{2}-[0-9]{2}$' THEN
        RETURN NULL;
    END IF;
    RETURN make_date(substr(v, 1, 4)::int, substr(v, 6, 2)::int, substr(v, 9, 2)::int);
EXCEPTION WHEN others THEN
    RETURN NULL;
END
$corps$

CREATE OR REPLACE FUNCTION ${database.defaultSchemaName}.document_echeance() RETURNS trigger LANGUAGE plpgsql AS $corps$
DECLARE
    t RECORD;
    depart DATE;
BEGIN
    SELECT duree_conservation_mois, point_depart, point_depart_index_code INTO t
      FROM ${database.defaultSchemaName}.type_document WHERE id = NEW.type_document_id;
    IF t.duree_conservation_mois IS NULL THEN
        NEW.echeance_conservation := NULL;
        RETURN NEW;
    END IF;
    depart := CASE t.point_depart
        WHEN 'DATE_DEPOT' THEN coalesce(NEW.created_at, now())::date
        WHEN 'METADONNEE' THEN ${database.defaultSchemaName}.meta_date(NEW.metadonnees, t.point_depart_index_code)
        ELSE NEW.date_document
    END;
    NEW.echeance_conservation := CASE WHEN depart IS NULL THEN NULL
        ELSE (depart + make_interval(months => t.duree_conservation_mois))::date END;
    RETURN NEW;
END
$corps$

CREATE OR REPLACE FUNCTION ${database.defaultSchemaName}.type_document_echeances() RETURNS trigger LANGUAGE plpgsql AS $corps$
BEGIN
    IF (NEW.duree_conservation_mois, NEW.point_depart, NEW.point_depart_index_code)
       IS DISTINCT FROM (OLD.duree_conservation_mois, OLD.point_depart, OLD.point_depart_index_code) THEN
        -- Réaffecter le type à lui-même déclenche le recalcul ligne à ligne.
        UPDATE ${database.defaultSchemaName}.document SET type_document_id = type_document_id WHERE type_document_id = NEW.id;
    END IF;
    RETURN NULL;
END
$corps$
